[metadata] {"type": "create", "filePath": "/workspace/repo/packages/next/src/views/Root/getCustomCollectionViewByRoute.ts", "content": "import type {
  AdminViewServerProps,
  PayloadComponent,
  SanitizedCollectionConfig,
} from 'payload'

import { isPathMatchingRoute } from './isPathMatchingRoute.js'

/**
 * Built-in view keys that should never be treated as custom collection views.
 */
const builtInViewKeys = ['edit', 'list']

export const getCustomCollectionViewByRoute = ({
  adminRoute,
  baseRoute,
  currentRoute: currentRouteWithAdmin,
  views,
}: {
  adminRoute: string
  baseRoute: string
  currentRoute: string
  views: SanitizedCollectionConfig['admin']['components']['views'] | undefined
}): {
  view: { payloadComponent?: PayloadComponent<AdminViewServerProps> }
  viewKey: null | string
} => {
  if (!views || typeof views !== 'object') {
    return {
      view: {},
      viewKey: null,
    }
  }

  const currentRoute =
    adminRoute === '/' ? currentRouteWithAdmin : currentRouteWithAdmin.replace(adminRoute, '')

  let viewKey: null | string = null

  const foundViewConfig = Object.entries(views).find(([key, view]) => {
    if (builtInViewKeys.includes(key)) {
      return false
    }

    if (
      !view ||
      typeof view !== 'object' ||
      !('path' in view) ||
      typeof view.path !== 'string' ||
      !('Component' in view)
    ) {
      return false
    }

    const isMatching = isPathMatchingRoute({
      currentRoute,
      exact: view.exact,
      path: `${baseRoute}${view.path}`,
      sensitive: view.sensitive,
      strict: view.strict,
    })

    if (isMatching) {
      viewKey = key
    }

    return isMatching
  })?.[1]

  if (!foundViewConfig || !('Component' in foundViewConfig)) {
    return {
      view: {},
      viewKey: null,
    }
  }

  return {
    view: {
      payloadComponent: foundViewConfig.Component as PayloadComponent<AdminViewServerProps>,
    },
    viewKey,
  }
}
